function pointIcon(it){const n=it.name.toLowerCase();if(/люстра|подвесной светильник/.test(n))return'chandelier';if(/светильник|спот|gx53|световая панель/.test(n))return'light';if(/карниз|гардин|штор/.test(n))return'curtain';if(/обход.*труб|печн.*труб/.test(n))return'pipe';if(/люк/.test(n))return'hatch';if(/колонн|балк/.test(n))return'column';if(/акустич/.test(n))return'acoustic';if(/вентилятор/.test(n))return'fan';if(/рекуператор|установк|бризер|камера смешения/.test(n))return'unit';if(/фильтр/.test(n))return'filter';if(/шумоглушител/.test(n))return'acoustic';if(/клапан|регулятор расхода/.test(n))return'valve';if(/отвод|тройник|крестовин|переход|муфта|ниппель|врезк|фланец|соединител/.test(n))return'fitting';if(/нагрев|охлад|увлажнит/.test(n))return'heater';if(/дренаж|сифон/.test(n))return'drain';if(/диффузор|анемостат/.test(n))return'diffuser';if(/решётка|решетка|зонт|дефлектор/.test(n))return'grille';if(/датчик|пульт|контроллер|термостат|реле|выключатель|камера/.test(n))return'sensor';return'custom'}
function lineIcon(it){const n=it.name.toLowerCase();if(/воздуховод/.test(n))return'duct';if(/свет|led|подсвет/.test(n))return'lightline';if(/карниз|гардин|ниша/.test(n))return'curtainline';if(/трек/.test(n))return'track';if(/кабель|гофра/.test(n))return'cable';if(/изоляц|греющий/.test(n))return'insulation';if(/профиль|вставка|гарпун/.test(n))return'profile';return'custom'}
