function allRows(r=room()){const rows=[];if(ceiling){for(const [id,qty,label] of [[r.materialId,Math.abs(area(r.vertices)),'Полотно: '],[r.profileId,perimeter(r.vertices),'Периметр: ']]){if(id&&byId[id])rows.push({key:'auto-'+id,name:label+byId[id].name,unit:byId[id].unit,qty:round(qty,2),price:price(id),kind:'material',auto:true,catId:id})}r.wallFinishes?.forEach((finish,i)=>{if(finish.material==='paint'||!wallMaterials[finish.material])return;const length=wallData(r.vertices,i).length,qty=round(length*num(r.ceilingHeight),2),id=`wall-${r.id}-${finish.id}`;rows.push({key:'auto-'+id,name:`Стена ${i+1}: ${wallMaterials[finish.material]}`,unit:'м²',qty,price:price(id),kind:'material',auto:true,catId:id});const profileId=`wall-profile-${r.id}-${finish.id}`;rows.push({key:'auto-'+profileId,name:`Стена ${i+1}: ${wallProfiles[finish.profile]||wallProfiles.shadow}`,unit:'м',qty:round(2*(length+num(r.ceilingHeight)),2),price:price(profileId),kind:'material',auto:true,catId:profileId});if(num(finish.acousticMm)>0){const backing=`backing-${r.id}-${finish.id}`;rows.push({key:'auto-'+backing,name:`Стена ${i+1}: ${wallBackings[finish.backing]||wallBackings.polyester} ${finish.acousticMm} мм`,unit:'м²',qty,price:price(backing),kind:'material',auto:true,catId:backing})}})}for(const it of r.items){rows.push({key:it.id,name:it.name+(it.size?' · '+it.size:''),unit:it.unit,qty:countItem(it),price:it.price??price(it.catId),kind:it.kind||'material',item:it})}return rows}
