 v.forEach((p,i)=>{const q=v[(i+1)%v.length],dx=q[0]-p[0],dy=q[1]-p[1],l=Math.hypot(dx,dy),nx=dy/l*.21,ny=-dx/l*.21,mx=(p[0]+q[0])/2,my=(p[1]+q[1])/2,sel=selected?.type==='wall'&&selected.index===i,wf=r.wallFinishes?.[i]||defaultWallFinish(),stretch=wf.material!=='paint',wallColor=/^#[0-9a-f]{6}$/i.test(wf.color||'')?wf.color:r.wallColor;st.push(`<line class="wall-finish ${stretch?'stretch-wall':''} ${sel?'selected-wall':''}" x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" style="stroke:${esc(wallColor)}"/>`);st.push(`<line class="wall-hit" data-kind="wall" data-index="${i}" x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}"/>`);st.push(`<text class="measurement" data-kind="wall" data-index="${i}" x="${mx+nx}" y="${my+ny}" text-anchor="middle">${fmt(l)} м</text>`);if(stretch)st.push(`<text class="wall-material-label" data-kind="wall" data-index="${i}" x="${mx+nx*2.05}" y="${my+ny*2.05}" text-anchor="middle">${wf.material==='acoustic'?'Тихая стена':'Натяжная стена'}</text>`)});
