function renderCatalog(){const cats=[...new Set(allCatalog().map(x=>x.category))],sel=$('catalog-category'),old=sel.value;sel.innerHTML='<option value="">Все категории</option>'+cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=cats.includes(old)?old:'';const query=$('catalog-search').value.trim().toLocaleLowerCase('ru'),category=sel.value,items=allCatalog().filter(x=>(!category||x.category===category)&&(!query||(x.name+' '+x.category).toLocaleLowerCase('ru').includes(query)));$('catalog-count').textContent=items.length+' вариантов';const list=$('catalog-list');let prev='',s='';for(const x of items){if(!query&&x.category!==prev){s+=`<div class="category-head">${esc(x.category)}</div>`;prev=x.category}s+=`<div class="catalog-item"><div><strong>${esc(x.name)}</strong><small>${esc(x.unit)} · ${x.place==='line'?'линия':'иконка'}${x.kind==='service'?' · работа':''}</small></div><div class="catalog-actions"><button type="button" class="estimate-only" data-estimateid="${esc(x.id)}" aria-label="Добавить только в смету: ${esc(x.name)}" title="Только в смету">Смета</button><button type="button" data-catid="${esc(x.id)}" aria-label="Добавить на план: ${esc(x.name)}" title="На план">+</button></div></div>`}list.innerHTML=s||'<p class="subtle">По запросу ничего не найдено. Добавьте свой вариант ниже.</p>'}
