function renderEstimate(){const rows=allRows(),list=$('estimate-list');let previous='',s='';for(const row of rows){const head=row.kind==='service'?'Работы':'Материалы и оборудование';if(head!==previous){s+=`<div class="estimate-heading">${head}</div>`;previous=head}s+=`<div class="estimate-row" data-row="${esc(row.key)}"><div class="name">${esc(row.name)}<small>${esc(row.unit)}${row.auto?' · автоматически':''}</small>${row.item?.place==='none'?`<button type="button" class="show-on-plan" data-showplan="${esc(row.key)}">Показать на плане</button>`:''}</div><input type="number" data-field="qty" min="0" step="0.01" aria-label="Количество: ${esc(row.name)}" value="${row.qty}" ${row.auto||row.item?.place==='line'&&row.unit==='м'?'disabled':''}><input type="number" data-field="price" min="0" step="1" aria-label="Цена: ${esc(row.name)}" value="${row.price}"><span class="line-total">${money(row.qty*row.price)}</span>${row.auto?'<span></span>':`<button type="button" data-remove="${esc(row.key)}" aria-label="Удалить ${esc(row.name)}">×</button>`}</div>`}list.innerHTML=s||'<p class="estimate-list-empty">Пока нет позиций. Добавьте их из каталога.</p>';let materials=0,services=0;rows.forEach(row=>{if(row.kind==='service')services+=row.qty*row.price;else materials+=row.qty*row.price});const projectTotal=state.rooms.reduce((sum,r)=>sum+allRows(r).reduce((v,x)=>v+x.qty*x.price,0),0);$('totals').innerHTML=`<div><span>Материалы и оборудование</span><b>${money(materials)}</b></div><div><span>Работы</span><b>${money(services)}</b></div><div class="grand"><span>Текущая комната</span><span>${money(materials+services)}</span></div>${state.rooms.length>1?`<div><span>Все помещения (${state.rooms.length})</span><b>${money(projectTotal)}</b></div>`:''}<p class="subtle">${rows.some(x=>!x.price)?'У части позиций цена 0 ₽. Заполните её перед использованием итога.':'Предварительно, до замера и согласования.'}</p>`;renderPrint(rows,materials,services)}
function renderPrint(rows,materials,services){let box=$('print-estimate');if(!box){box=document.createElement('div');box.id='print-estimate';box.className='print-estimate';$('board').appendChild(box)}box.innerHTML=`<h2>ПОТОК+ · ${ceiling?'Модель комнаты':'Вент2D'}</h2><p>${esc(room().name)} · ${fmt(Math.abs(area(room().vertices)))} м² · высота ${fmt(room().ceilingHeight)} м</p><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">Позиция</th><th>Кол-во</th><th>Ед.</th><th>Цена</th><th>Сумма</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td align="right">${x.qty}</td><td align="center">${esc(x.unit)}</td><td align="right">${money(x.price)}</td><td align="right">${money(x.qty*x.price)}</td></tr>`).join('')}</tbody></table><p><b>Материалы: ${money(materials)} · Работы: ${money(services)} · Итого: ${money(materials+services)}</b></p><p>Предварительно. Размеры, объёмы и цены уточняются после замера.</p>`}
