function renderPlanPicker(){const walls=ceiling?Object.entries(wallMaterials).filter(([id])=>id!=='paint').map(([id,name])=>({id:'wall:'+id,category:'Натяжные стены',name,place:'wallFinish',unit:'стена'})):[],all=allCatalog().concat(walls),cats=[...new Set(all.map(x=>x.category))],sel=$('plan-pick-category'),old=sel.value;sel.innerHTML='<option value="">Все категории</option>'+cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=cats.includes(old)?old:'';const q=$('plan-pick-search').value.trim().toLocaleLowerCase('ru'),entries=all.filter(x=>(!sel.value||x.category===sel.value)&&(!q||(x.name+' '+x.category).toLocaleLowerCase('ru').includes(q)));let group='',html='';for(const cat of entries){if(!q&&group!==cat.category){group=cat.category;html+=`<div class="plan-pick-group">${esc(group)}</div>`}html+=`<button type="button" data-pickid="${esc(cat.id)}"><span>${esc(cat.name)}</span><small>${cat.place==='wallFinish'?'на стену':ceiling&&cat.category==='Полотна'?'вся площадь':cat.place==='line'?'линия':esc(cat.unit)}</small></button>`}$('plan-pick-list').innerHTML=html||'<p class="subtle">Ничего не найдено. Свой вариант можно добавить в каталоге справа.</p>'}
