function addPlaced(cat,x,y,x2,y2,wallIndex=null){mutate(()=>{const it={id:uid(),catId:cat.id,name:cat.name,unit:cat.unit,place:cat.place,kind:cat.kind||'material',qty:1,price:price(cat.id),size:'',color:'#ed9e67',system:/приток|Приточ|воздухозабор/i.test(cat.name)?'Приток':/вытяж|Вытяж|выброс/i.test(cat.name)?'Вытяжка':'Нейтрально',airflow:0,x:round(x),y:round(y),...(cat.place==='line'?{x2:round(x2),y2:round(y2)}:{})};room().items.push(it);if(wallIndex!==null){const w=wallData(room().vertices,wallIndex),mx=(it.x+it.x2)/2,my=(it.y+it.y2)/2;bindLine(it,wallIndex,clamp((mx-w.a[0])*w.ux+(my-w.a[1])*w.uy,0,w.length))}});selected={type:'item',id:room().items.at(-1).id};pending=null;draftStart=null;renderBoard();toast('На плане: '+cat.name+' · X '+fmt(x)+' м, Y '+fmt(y)+' м')}
