$('inspector').addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action||!selected)return;if(action==='dismiss'){selected=null;renderBoard();return}if(action==='minimize'){inspectorMinimized=!inspectorMinimized;const el=$('inspector');el.classList.toggle('is-minimized',inspectorMinimized);const button=e.target.closest('button');button.textContent=inspectorMinimized?'Развернуть':'Свернуть';button.setAttribute('aria-label',(inspectorMinimized?'Развернуть':'Свернуть')+' свойства');button.setAttribute('aria-expanded',String(!inspectorMinimized));return}if(selected.type!=='item')return;const it=room().items.find(x=>x.id===selected.id);if(!it)return;if(action==='delete'){mutate(()=>room().items=room().items.filter(x=>x.id!==it.id));selected=null}else if(action==='duplicate'){mutate(()=>{const copy={...it,id:uid(),x:it.x+.2,y:it.y+.2,...(it.place==='line'?{x2:it.x2+.2,y2:it.y2+.2}:{})};if(it.wallBinding){copy.wallBinding={...it.wallBinding,offset:it.wallBinding.offset+.2};room().items.push(copy);syncWallLine(copy)}else room().items.push(copy)});selected={type:'item',id:room().items.at(-1).id}}render()});
