$('save-svg').addEventListener('click',()=>{const svg=$('plan').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1200');svg.setAttribute('height','800');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.grid-line{stroke:#cfddda;stroke-width:.008}.room-fill{stroke:#284d5a;stroke-width:.045}.wall-hit{stroke:transparent;stroke-width:.22}.vertex{fill:#184452;stroke:#fff;stroke-width:.035}.measurement,.item-tag,.item-variant{font-size:.16px;fill:#12333e;font-weight:bold;paint-order:stroke;stroke:#fff;stroke-width:.045}.icon-back{fill:#fff;stroke:currentColor;stroke-width:.035}.item-line{stroke:currentColor;stroke-width:.095}.item-line-secondary{stroke:currentColor;stroke-width:.025}.item-hit{stroke:transparent;stroke-width:.27}.wall-index{font-size:.13px;fill:#697b7f}.dimension{stroke:#397c88;stroke-width:.018;stroke-dasharray:.06 .04;fill:#216573}.dimension text{font-size:.145px;fill:#1c5360;font-weight:bold;paint-order:stroke;stroke:#fff;stroke-width:.045}.dimension-active{stroke:#bb6739}.line-handle{fill:#fff;stroke:#ce6e35;stroke-width:.045}';svg.insertBefore(style,svg.firstChild);download('potok-plan-'+filename(room().name)+'.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml')});
